INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','easy','flashcard','What are the two main types of emphysema and their distribution within the acinus?','["Centriacinar (centrilobular) emphysema — affects the central/proximal parts of the acinus (respiratory bronchioles), predominantly in upper lobes, caused by smoking. Panacinar (panlobular) emphysema — affects the entire acinus uniformly, predominantly in lower lobes, associated with alpha-1 antitrypsin deficiency."]','A','Mnemonic: CEntriACInar = Central + smoking (CigarettE); PANACINar = full acinus + AAT deficiency (PAN = all).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','easy','flashcard','What is alpha-1 antitrypsin (AAT) deficiency and which emphysema type does it cause?','["Alpha-1 antitrypsin (AAT) is encoded at the Pi locus on chromosome 14. It inhibits neutrophil elastase. The ZZ genotype causes markedly reduced serum AAT, resulting in panacinar emphysema predominantly at the lung bases, presenting at a younger age (40s-50s). Smoking markedly accelerates disease."]','A','Pi locus on chromosome 14. ZZ = worst. AAT deficiency → uninhibited elastase → panacinar emphysema (bases).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','medium','flashcard','What is the pathogenetic mechanism (protease-antiprotease hypothesis) of emphysema?','["Cigarette smoke: (1) recruits neutrophils/macrophages releasing elastase and other proteases; (2) generates reactive oxygen species that inactivate alpha-1 antitrypsin. This protease-antiprotease imbalance leads to unchecked destruction of alveolar walls and loss of elastic tissue, causing permanent airspace enlargement."]','A','Smoke → more protease + less antiprotease → elastin destroyed → airspace enlargement. NRF2 is a protective transcription factor (upregulates antioxidant genes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','medium','flashcard','What are the clinical features of the ''''pink puffer'''' phenotype associated with emphysema?','["Pink puffer (emphysema-predominant COPD): (1) barrel chest from hyperinflation; (2) pursed-lip breathing; (3) diminished breath sounds; (4) weight loss; (5) relatively normal PaO2 maintained by hyperventilation; (6) low diffusion capacity (DLCO); (7) hyperinflation on CXR with flattened diaphragms. Minimal cyanosis and peripheral edema."]','A','Pink (maintained O2 by hyperventilating) + Puffer (pursed lips). Contrast with Blue Bloater (chronic bronchitis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','medium','flashcard','What is distal acinar (paraseptal) emphysema and what is its clinical significance?','["Distal acinar emphysema (paraseptal emphysema) affects the distal acinus adjacent to the pleura and interlobular septa. It may form cyst-like spaces >2 cm called bullae. Clinical significance: it is the underlying cause of spontaneous pneumothorax in young adults. It is usually NOT associated with severe COPD but can be associated with scarring."]','A','Paraseptal → near pleura → bullae → spontaneous pneumothorax in young adults. Young man + sudden chest pain + dyspnea = paraseptal emphysema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','medium','flashcard','What gross and microscopic changes are seen in the lungs of emphysema patients?','["Gross: lungs are voluminous, pale, soft, and spongy; may show bullae (>1 cm enlarged spaces). Microscopic: abnormally large airspaces with destruction and disappearance of alveolar walls; loss of elastic tissue; capillary reduction. No fibrosis. Lungs often do NOT fully deflate."]','A','Emphysema = MORE air, LESS wall. Soft, large, pale lungs. No interstitial fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','medium','flashcard','What pulmonary function changes are characteristic of emphysema?','["FEV1 decreased; FVC may be decreased or normal; FEV1/FVC ratio <0.7 (obstructive pattern). Total lung capacity increased (hyperinflation). Residual volume increased. DLCO (diffusion capacity) decreased due to loss of alveolar surface area. Response to bronchodilators limited (structural, not reversible)."]','A','Obstructive pattern (FEV1/FVC <0.7) + low DLCO (lost alveolar surface) + high TLC (hyperinflation). Little bronchodilator response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','hard','flashcard','How does emphysema cause expiratory airflow obstruction despite no intrinsic airway narrowing?','["In emphysema, destruction of alveolar walls eliminates the radial traction that normally holds respiratory bronchioles open during expiration. Without this elastic recoil support, small airways collapse during forced expiration, trapping air. This is a dynamic collapse: airways are not permanently narrowed but collapse because surrounding support tissue is destroyed."]','A','Key concept: radial traction lost → small airways collapse on expiration → air trapping. The obstruction is FUNCTIONAL (loss of support), not structural.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','hard','flashcard','What is the role of NRF2 in the pathogenesis of emphysema?','["NRF2 (nuclear factor erythroid 2-related factor 2) is a transcription factor in alveolar epithelial cells that senses oxidant stress and upregulates antioxidant genes protecting against oxidative damage. Mice lacking NRF2 are significantly more sensitive to tobacco smoke. Genetic variants in NRF2 and its targets are associated with smoking-related emphysema."]','A','NRF2 = guardian against oxidant stress in lung. Loss → susceptibility to emphysema from smoking. NRF2 target genes include heme oxygenase-1 (HO-1).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Emphysema','hard','flashcard','What mechanisms link emphysema to pulmonary hypertension and cor pulmonale?','["Emphysema → hypoxemia (from V/Q mismatch) → hypoxic pulmonary vasoconstriction → chronic elevation of pulmonary vascular resistance → pulmonary hypertension → right ventricular hypertrophy (cor pulmonale). Additionally, destruction of alveolar walls reduces the cross-sectional area of the pulmonary vascular bed, further increasing vascular resistance."]','A','Two mechanisms: (1) Hypoxia → vasoconstriction → PHT; (2) Capillary loss → reduced vascular bed → PHT. Together → cor pulmonale (RV hypertrophy) → eventual right heart failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','easy','flashcard','What is the clinical definition of chronic bronchitis?','["Chronic bronchitis is defined clinically as persistent productive cough for at least 3 consecutive months in at least 2 consecutive years, in a patient in whom other causes (TB, bronchiectasis, etc.) have been excluded. It is NOT a histologic or radiologic diagnosis but a clinical one based on symptom duration."]','A','3 months × 2 years = chronic bronchitis. Must exclude other causes. Remember: clinical definition, not pathologic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','easy','flashcard','What is the Reid index and what does it measure?','["The Reid index is the ratio of the thickness of the mucous gland layer to the total bronchial wall thickness (from epithelium to perichondrium). Normal: ≤0.4. In chronic bronchitis: >0.4 due to hypertrophy and hyperplasia of submucosal mucous glands. It correlates with the severity of mucus hypersecretion."]','A','Reid index = gland thickness / wall thickness. Normal ≤0.4. Chronic bronchitis >0.4. REID = Ratio Exceeds IDeal in bronchitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','medium','flashcard','What are the microscopic features of chronic bronchitis?','["1) Hypertrophy and hyperplasia of submucosal mucous glands (increased Reid index >0.4). 2) Goblet cell hyperplasia extending into bronchioles (normally absent there). 3) Inflammatory infiltrate: neutrophils acutely; lymphocytes and macrophages chronically. 4) Small airway disease: mucus plugging, smooth muscle hyperplasia, peribronchial fibrosis of bronchioles. 5) Squamous metaplasia of bronchial epithelium."]','A','Hallmarks: big glands (Reid >0.4) + goblet cells in bronchioles + inflammation + small airway fibrosis. Squamous metaplasia → malignant potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','medium','flashcard','What is the ''''blue bloater'''' phenotype of chronic bronchitis?','["Blue bloater (chronic bronchitis-predominant COPD): (1) cyanosis from chronic hypoxemia and hypercapnia; (2) peripheral edema from cor pulmonale/right heart failure; (3) obesity; (4) polycythemia; (5) productive cough. PFTs: FEV1/FVC <0.7, reduced FEV1, preserved DLCO (unlike emphysema). PaO2 decreased, PaCO2 elevated (CO2 retainer)."]','A','Blue = cyanotic (low O2, high CO2). Bloater = edematous (cor pulmonale). Contrast: Pink Puffer (emphysema) maintains PaO2 by hyperventilating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','medium','flashcard','How does cigarette smoke cause mucus hypersecretion in chronic bronchitis?','["Cigarette smoke directly irritates the bronchial mucosa, causing: (1) stimulation of goblet cells and submucosal glands to hyperplasia/hypertrophy; (2) impairment of mucociliary clearance (paralyzes cilia); (3) recruitment of inflammatory cells releasing mediators that further stimulate mucus secretion; (4) squamous metaplasia replacing ciliated epithelium."]','A','Smoke → goblet hyperplasia + gland hypertrophy + ciliary dysfunction + inflammation = mucus stasis = chronic infection cycle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','medium','flashcard','What bacteria most commonly cause acute exacerbations of chronic bronchitis?','["Most common: Haemophilus influenzae (non-typeable), Moraxella catarrhalis, and Streptococcus pneumoniae. Viruses (especially rhinovirus and influenza) also trigger exacerbations. In severe/advanced COPD: Pseudomonas aeruginosa. These organisms exploit the impaired mucociliary clearance and colonize the lower airways."]','A','H. influenzae #1, M. catarrhalis #2, S. pneumoniae #3 for COPD exacerbations. Severe COPD → Pseudomonas. Viruses (rhinovirus) trigger many exacerbations too.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','medium','flashcard','How does small airway disease contribute to the obstruction in chronic bronchitis?','["Small airway disease (chronic bronchiolitis) contributes to irreversible airflow obstruction via: (1) mucus plugging of bronchiolar lumina; (2) smooth muscle hyperplasia and bronchospasm; (3) peribronchial fibrosis narrowing the bronchiolar lumen; (4) inflammatory infiltrate thickening the wall. Together these changes reduce bronchiolar caliber and airflow."]','A','Bronchiolitis = mucus + fibrosis + smooth muscle + inflammation → fixed (irreversible) narrowing of small airways. This is the main site of resistance in COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','hard','flashcard','What is the mechanism of hypercapnia in chronic bronchitis, and how does it differ from emphysema?','["In chronic bronchitis, airway obstruction and mucus plugging cause ventilation-perfusion mismatch. These patients hypoventilate (blunted hypercapnic respiratory drive, often due to obesity). CO2 retention (hypercapnia) results. In emphysema, patients hyperventilate to maintain oxygenation, maintaining PaCO2. Hence chronic bronchitis → CO2 retainers (blue bloaters); emphysema → CO2 normal/low (pink puffers)."]','A','Chronic bronchitis = hypoventilator → CO2 retention (blunted drive). Emphysema = hyperventilator → normal CO2 (high drive). Both: V/Q mismatch, but different compensation strategy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','hard','flashcard','How does chronic bronchitis progress to cor pulmonale?','["Mucus plugging and airway obstruction → chronic hypoxemia → hypoxic pulmonary vasoconstriction → chronic pulmonary hypertension → increased right ventricular afterload → right ventricular hypertrophy → eventual right ventricular failure (cor pulmonale). Secondary polycythemia from EPO production in response to hypoxia also increases blood viscosity, further straining the right heart."]','A','Hypoxia → vasoconstriction → PHT → RV hypertrophy → cor pulmonale. Polycythemia from EPO increases viscosity (more RV work). Peripheral edema signals RV failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Obstructive Lung Disease — Chronic Bronchitis','hard','flashcard','What distinguishes mucus gland changes in chronic bronchitis from normal airways, and where are goblet cells normally absent?','["In normal airways: mucous glands and goblet cells are present in trachea and bronchi but NOT in bronchioles. In chronic bronchitis: mucous glands are hypertrophied (Reid >0.4) throughout the bronchial tree, AND goblet cell hyperplasia extends into bronchioles where goblet cells are normally absent. This extension is pathognomonic of chronic bronchitis at the bronchiolar level."]','A','Key: goblet cells should NOT be in bronchioles. Finding them there = chronic bronchitis. Also: glands should be thin (Reid ≤0.4); thick glands = disease.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','easy','flashcard','What are the classic morphologic findings in the sputum of an asthmatic patient?','["1) Curschmann spirals — whorled mucus plugs cast from small bronchioles. 2) Charcot-Leyden crystals — bipyramidal needle-like crystals derived from eosinophil granule proteins (lysophospholipase). 3) Creola bodies — clusters of shed airway epithelial cells. 4) Increased eosinophils."]','A','CCC: Curschmann + Charcot-Leyden + eosinophilia = asthma sputum. Curschmann = mucus casts. Charcot-Leyden = eosinophil crystals.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','easy','flashcard','What is the immunoglobulin responsible for atopic asthma and what cells does it sensitize?','["IgE mediates atopic (extrinsic/allergic) asthma. B cells (stimulated by IL-4 and IL-13 from TH2 cells) produce IgE, which binds to Fc-epsilon receptors on mast cells and basophils, sensitizing them. On re-exposure to allergen, cross-linking of IgE triggers degranulation and release of bronchoconstrictor mediators."]','A','TH2 → IL-4/13 → IgE production → mast cell sensitization → allergen re-exposure → degranulation → bronchospasm. IgE = type I (immediate) hypersensitivity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','medium','flashcard','What are the TH2 cytokines in atopic asthma and what does each do?','["IL-4: stimulates B cell class switching to IgE production; promotes goblet cell hyperplasia. IL-5: activates eosinophils, promotes eosinophil survival and degranulation. IL-13: promotes IgE production; stimulates mucus secretion from goblet cells. IL-9: mast cell growth factor. Together, these cytokines drive the allergic/atopic inflammatory response."]','A','IL-4 = IgE; IL-5 = Eosinophils; IL-13 = mucus + IgE. Mnemonic: 4 IgE, 5 Eos, 13 mucus. IL-13 polymorphisms have strongest genetic association with asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','medium','flashcard','What histologic features are seen in the airways of chronic asthmatics (airway remodeling)?','["1) Thickened basement membrane (subepithelial fibrosis). 2) Smooth muscle hypertrophy and hyperplasia. 3) Mucosal edema and neovascularization. 4) Dense inflammatory infiltrate: eosinophils, mast cells, TH2 lymphocytes, and basophils. 5) Mucous gland hypertrophy with goblet cell hyperplasia. 6) Bronchial wall thickening overall."]','A','6 features of remodeling: BM thick + SM hyper + edema + vessels + eos/mast cells + glands. Thickened BM is the hallmark on biopsy — seen even in mild/moderate disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','medium','flashcard','What is the early-phase and late-phase response in allergic asthma?','["Early phase (minutes to 1 hour): IgE-mediated mast cell degranulation releasing histamine, leukotrienes C4/D4/E4, and prostaglandin D2 → immediate bronchospasm, mucus secretion, vascular permeability. Late phase (6-8 hours): TH2 cytokine-driven recruitment of eosinophils, basophils, and T cells → prolonged inflammation and bronchospasm."]','A','Early = mast cells (minutes). Late = eosinophils/T cells (hours). The late phase causes more persistent asthma; corticosteroids suppress the late phase more than antihistamines.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','medium','flashcard','Define status asthmaticus and state its clinical risk.','["Status asthmaticus is a state of unremitting severe asthma attacks that fail to respond to standard bronchodilator therapy and may prove fatal. It is a medical emergency characterized by progressive respiratory failure from sustained bronchospasm, mucus plugging, and air trapping. Patients typically have a history of severe or poorly controlled asthma. Mechanical ventilation may be required."]','A','Status asthmaticus = asthma that won''''t stop → medical emergency → can be fatal. Not just a bad attack — it is UNREMITTING. May require intubation and ICU care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','medium','flashcard','What is occupational asthma and name four causative agents?','["Occupational asthma is triggered by workplace exposure to sensitizing agents. Examples: (1) toluene diisocyanate (TDI) — plastics/paints; (2) trimellitic anhydride — epoxy resins; (3) wood dust (western red cedar); (4) animal proteins (lab workers). Mechanisms vary: IgE-mediated, direct bronchoconstrictor release, or unknown. Only small quantities are needed after sensitization."]','A','Occupational asthma = work + wheeze. TDI (plastics), wood dust, animal proteins are classic triggers. Multiple mechanisms possible. 15% of adult-onset asthma is occupational.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','hard','flashcard','What is aspirin-sensitive (NSAID-induced) asthma and what is the mechanism?','["Aspirin/NSAID asthma is triggered by COX inhibition. This blocks prostaglandin E2 (PGE2) production, which normally inhibits leukotriene synthesis. With PGE2 reduced, arachidonic acid is shunted to the 5-lipoxygenase pathway, producing excess cysteinyl leukotrienes (LTC4, LTD4, LTE4) → bronchoconstriction. Associated with nasal polyps and chronic rhinosinusitis (Samter triad)."]','A','Samter triad: asthma + nasal polyps + aspirin sensitivity. COX inhibition → less PGE2 → more leukotrienes (lipoxygenase shunt) → bronchospasm. Treat with leukotriene modifiers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','hard','flashcard','Compare the two main genetic susceptibility loci for asthma on chromosomes 5q and 20p.','["Chromosome 5q: contains the IL-3, IL-4, IL-5, IL-9, IL-13, and IL-4 receptor gene cluster. Polymorphisms here (especially IL-13) have the strongest/most consistent association with asthma. Chromosome 20p: contains the ADAM33 locus, a metalloprotease expressed in bronchial smooth muscle and fibroblasts — variants associated with airway hyperresponsiveness and remodeling."]','A','5q = cytokine cluster (IL-4, IL-5, IL-13) → atopy/IgE. 20p = ADAM33 → smooth muscle remodeling. IL-13 variants at 5q have the strongest genetic signal for atopic asthma.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Asthma','hard','flashcard','What is the difference between eosinophilic (type 2 high) and neutrophilic (type 2 low) asthma?','["Eosinophilic (type 2 high / TH2-high) asthma: atopic, IgE-mediated or IL-5 driven; responds well to corticosteroids and anti-IL-5 biologics (mepolizumab). Neutrophilic (type 2 low): associated with obesity, smoking, and occupational exposures; corticosteroid-resistant; may involve TH17 pathways and IL-17. About one-half of asthma cases are non-allergic."]','A','Eosinophilic = TH2 high = steroid-responsive = anti-IL5 target. Neutrophilic = TH2 low = steroid-resistant = tougher to treat. Key for personalized medicine: phenotyping asthma drives biologic selection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','easy','flashcard','Define bronchiectasis and name the two fundamental conditions required for its development.','["Bronchiectasis is permanent, irreversible dilation of bronchi and bronchioles caused by destruction of smooth muscle and elastic tissue, resulting from chronic necrotizing infections. The two fundamental conditions required: (1) OBSTRUCTION — impairs mucociliary clearance allowing secretions to pool; (2) INFECTION — causes inflammation, necrosis, and wall destruction leading to dilation."]','A','OBSTRUCTION + INFECTION = Bronchiectasis. Neither alone is usually sufficient. They create a vicious cycle: obstruction → pooling → infection → destruction → more dilation → more obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','easy','flashcard','What are the most common hereditary causes of bronchiectasis?','["1) Cystic fibrosis (CFTR mutation) — most common hereditary cause; causes thick viscous secretions, impaired mucociliary clearance, chronic Pseudomonas infection. 2) Primary ciliary dyskinesia (Kartagener syndrome) — dynein arm mutations cause immotile cilia and impaired clearance. 3) IgA deficiency and other immunodeficiencies — impaired humoral immunity allows recurrent respiratory infections."]','A','CF = #1 hereditary cause. PCD/Kartagener = immotile cilia. Immunodeficiency = recurrent infections → bronchiectasis. Immotile + situs inversus + bronchiectasis = Kartagener.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','medium','flashcard','Describe the classic clinical presentation of bronchiectasis.','["1) Chronic productive cough with large volumes of purulent sputum (>100 mL/day). 2) Foul-smelling sputum from anaerobic bacteria. 3) Paroxysms of coughing on arising in the morning (positional drainage of pooled secretions). 4) Hemoptysis. 5) Digital clubbing. 6) Recurrent respiratory infections. 7) Bilateral coarse crackles. HRCT shows bronchial dilation with signet ring sign (bronchus wider than adjacent artery)."]','A','Classic: copious purulent sputum + morning paroxysms + hemoptysis + clubbing + recurrent infections. HRCT signet ring = dilated bronchus > adjacent artery. Tram-track lines on CXR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','medium','flashcard','What organisms characteristically colonize the airways in cystic fibrosis-associated bronchiectasis?','["Early CF: Staphylococcus aureus and Haemophilus influenzae. Later CF: Pseudomonas aeruginosa (mucoid form), which is most characteristic. Mucoid Pseudomonas forms biofilms resistant to antibiotics. Also: Burkholderia cepacia (worse prognosis), Stenotrophomonas, non-tuberculous mycobacteria."]','A','CF microbiology timeline: early = S. aureus/H. influenzae → later = mucoid Pseudomonas (worst, biofilm-forming) → Burkholderia cepacia (worse still). Mucoid Pseudomonas = CF signature pathogen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','medium','flashcard','What are the gross morphologic types of bronchiectasis?','["Three types by shape on imaging/pathology: (1) Cylindrical — uniform tubular dilation; most common. (2) Varicose — irregular/beaded dilation resembling varicose veins. (3) Saccular (cystic) — progressive outward ballooning forming cyst-like structures (worst type; indicates most destruction). All types are permanent and irreversible."]','A','Three types: Cylindrical (tube) → Varicose (beaded) → Saccular (cysts) = increasing severity. Saccular = most destructive. Lower lobes = most affected (gravity-dependent pooling).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','medium','flashcard','What is the pathology seen at autopsy or resection in bronchiectasis?','["Grossly: markedly dilated bronchi filled with purulent exudate, extending to within 1-2 cm of the pleura (normally bronchi do not reach the pleura). Microscopically: acute and chronic bronchial and peribronchial inflammation, epithelial ulceration and loss of cilia, squamous metaplasia, fibrosis of bronchial walls, and obliteration of distal bronchioles."]','A','Grossly: pus-filled dilated bronchi near pleura. Micro: ulceration, squamous metaplasia, fibrosis, inflammation. Key: bronchi normally STOP before the pleura; in bronchiectasis they reach to 1-2 cm from pleural surface.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','medium','flashcard','What systemic complications can arise from severe untreated bronchiectasis?','["1) Cor pulmonale and right heart failure from chronic hypoxemia. 2) Brain abscesses from hematogenous spread of infection. 3) Secondary AA amyloidosis causing nephrotic syndrome and renal failure. 4) Massive hemoptysis from erosion into bronchial arteries. 5) Respiratory failure. Modern antibiotics and physiotherapy have made these less common."]','A','Complications: cor pulmonale, brain abscess, amyloidosis, hemoptysis, respiratory failure. Robbins notes these are now less common with modern antibiotics and physiotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','hard','flashcard','How does Kartagener syndrome (primary ciliary dyskinesia) cause bronchiectasis and what accounts for situs inversus?','["PCD is caused by mutations in dynein arm proteins of cilia (e.g., DNAI1, DNAH5). Immotile/dysfunctional cilia → impaired mucociliary clearance → retained secretions → recurrent infections → bronchiectasis. Additionally, normal organ rotation during embryogenesis requires ciliary movement to establish left-right asymmetry; without ciliary function, rotation becomes random → situs inversus in ~50% of cases."]','A','PCD → immotile cilia → bronchiectasis + sinusitis. Situs inversus in 50% because embryonic organ rotation requires normal ciliary function for left-right determination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','hard','flashcard','What is allergic bronchopulmonary aspergillosis (ABPA) and how does it cause bronchiectasis?','["ABPA is a hypersensitivity reaction to Aspergillus fumigatus colonizing the airways. It occurs in asthmatics and CF patients. Type I (IgE) + type III (immune complex) hypersensitivity responses lead to eosinophilic bronchitis. Recurrent inflammation and mucus plugging damage bronchial walls, causing proximal (central) bronchiectasis. Diagnosed by elevated serum IgE, anti-Aspergillus IgE/IgG, peripheral eosinophilia, and HRCT showing central bronchiectasis."]','A','ABPA: Aspergillus in asthmatic/CF airways → IgE + immune complex reaction → central bronchiectasis. Treated with corticosteroids ± itraconazole. Elevated IgE is the diagnostic clue.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Bronchiectasis','hard','flashcard','Why is bronchiectasis irreversible while asthmatic bronchoconstriction is reversible?','["Asthma: airway narrowing is functional — smooth muscle spasm and mucosal edema. These resolve with bronchodilators and steroids because the structural wall is intact. Bronchiectasis: chronic necrotizing infection causes destruction of smooth muscle, elastic tissue, and cartilage in bronchial walls, replacing them with fibrous scar tissue. This structural damage is permanent and irreversible."]','A','Asthma = functional narrowing (reversible). Bronchiectasis = structural destruction (irreversible). Key: elastic tissue + smooth muscle + cartilage destroyed and replaced by fibrosis = cannot be reversed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','easy','flashcard','What are the key features of the UIP (usual interstitial pneumonia) pattern on biopsy and HRCT?','["Histology: patchy interstitial fibrosis with TEMPORAL HETEROGENEITY (fibroblastic foci = early lesions; dense collagen = old lesions, present in same biopsy). Subpleural and basal predominance. Honeycomb change ± fibroblastic foci. HRCT: subpleural, basal-predominant reticular opacities, honeycombing ± traction bronchiectasis; minimal ground glass. UIP = IPF histologically."]','A','UIP hallmarks: temporal heterogeneity (old scar + new fibroblastic focus in same biopsy) + subpleural/basal. HRCT: honeycombing + traction bronchiectasis. UIP = think IPF until proven otherwise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','easy','flashcard','What is honeycombing and what disease does it represent?','["Honeycombing is the HRCT and gross pathologic pattern of end-stage fibrotic lung disease. Grossly and on CT: irregular cystic spaces (typically 3-10 mm, clustered) lined by fibrous tissue, creating a honeycomb appearance, predominantly subpleural. Microscopically: bronchiolar-lined cysts within dense fibrosis. It signifies severe, irreversible lung destruction."]','A','Honeycombing = end-stage fibrosis. HRCT: peripheral, subpleural, clustered cysts. Histology: bronchiolar-lined cysts in fibrosis. When you see honeycombing = IPF/UIP until proven otherwise.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','medium','flashcard','What is the difference between IPF/UIP, NSIP, and COP in terms of prognosis and steroid response?','["IPF/UIP: worst prognosis (median survival 3 years); resistant to steroids; only pirfenidone/nintedanib slow progression; lung transplant is only cure. NSIP: much better prognosis; associated with CTD; often responds to corticosteroids. COP (cryptogenic organizing pneumonia): good prognosis; responds well to corticosteroids — often dramatic improvement."]','A','Prognosis: COP (best, steroid-responsive) > NSIP (good, steroid-responsive) >> IPF/UIP (poor, steroid-resistant). If ILD responds dramatically to steroids = probably COP or NSIP, not IPF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','medium','flashcard','What are the histologic features of NSIP (nonspecific interstitial pneumonia)?','["NSIP shows: (1) uniform (temporally homogeneous) interstitial inflammation and/or fibrosis — unlike UIP''''s temporal heterogeneity; (2) diffuse alveolar wall thickening; (3) fibroblastic foci absent or rare; (4) subpleural sparing may be present. Two subtypes: cellular NSIP (mostly inflammation) and fibrotic NSIP (fibrosis predominant). Associated with systemic sclerosis, polymyositis/dermatomyositis."]','A','NSIP = UNIFORM (same age lesions throughout). UIP = PATCHY (old + new lesions together). Temporal homogeneity is the key histologic distinction of NSIP from UIP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','medium','flashcard','What are the characteristic features of COP (cryptogenic organizing pneumonia)?','["COP: (1) polypoid plugs of loose organizing connective tissue (Masson bodies) in alveolar ducts, alveoli, and bronchioles; (2) temporally homogeneous lesions; (3) preserved lung architecture; (4) mild interstitial inflammation. HRCT: bilateral, peripheral, consolidative or ground-glass opacities (reverse halo or atoll sign). Responds dramatically to corticosteroids."]','A','COP = Masson bodies (organizing fibroblast plugs in alveoli/ducts) + preserved architecture + homogeneous + steroid-responsive. Reverse halo sign on CT. Does not respond to antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','medium','flashcard','What genetic mutations are associated with familial IPF and what do they suggest about pathogenesis?','["Familial IPF is associated with: (1) TERT/TERC mutations — telomerase components; telomere shortening causes alveolar epithelial cell senescence. (2) MUC5B variants — common variant causing increased MUC5B mucin secretion (present in ~1/3 of IPF). (3) SFTPC/SFTPB — surfactant protein mutations in some familial forms. These genes all point to alveolar epithelial injury/aging as the initiating event."]','A','IPF genetics: TERT/TERC (telomere shortening → cell aging) + MUC5B variant (increased mucin) → alveolar epithelial injury → aberrant repair → fibrosis. Concept: IPF = disease of accelerated lung aging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','medium','flashcard','What are the pulmonary function findings in restrictive lung disease?','["Pattern: REDUCED total lung capacity (TLC), forced vital capacity (FVC), and FEV1; NORMAL or ELEVATED FEV1/FVC ratio (unlike obstruction where ratio falls). Residual volume may be normal or reduced. DLCO (diffusion capacity) is reduced. Lung compliance is reduced (stiff lungs)."]','A','Restrictive PFTs: TLC down, FVC down, FEV1 down, FEV1/FVC NORMAL or UP, DLCO down, Compliance down. Opposite of obstruction where TLC up and ratio down. Think: restrictive = everything shrinks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','hard','flashcard','What is the proposed pathogenesis of IPF starting from alveolar epithelial injury?','["Current model: (1) Repetitive subclinical injury to alveolar type II cells (from telomere shortening, infections, microaspiration, toxins). (2) Impaired epithelial repair due to senescent/apoptotic type II cells. (3) Release of TGF-beta and other profibrotic cytokines. (4) Activation of fibroblasts → myofibroblasts. (5) Excessive ECM deposition (collagen). (6) Progressive fibrosis replaces normal lung parenchyma. Fibroblastic foci represent the active leading edge."]','A','IPF mechanism: injured epithelium → TGF-beta → myofibroblast activation → collagen deposition → fibrosis. Fibroblastic foci = active fibrogenesis. Telomere shortening → type II cell senescence = initial trigger.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','hard','flashcard','Which ILD patterns are associated with connective tissue diseases, and which pattern is most common in scleroderma?','["Connective tissue diseases (CTD) can cause multiple ILD patterns. Scleroderma/systemic sclerosis → NSIP most common (also UIP). Rheumatoid arthritis → UIP or NSIP. Polymyositis/dermatomyositis → NSIP or COP. SLE → rare ILD, mainly serositis/DAD. Sjögren syndrome → lymphoid interstitial pneumonia (LIP)."]','A','CTD-ILD patterns: Scleroderma → NSIP #1. RA → UIP or NSIP. PM/DM → NSIP or COP. Sjögren → LIP. CTD-ILD often more steroid-responsive than idiopathic IPF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Restrictive Lung Disease — Interstitial Lung Diseases','hard','flashcard','Why does cobblestoning of the pleural surface occur in IPF, and what is the cut surface appearance?','["The pleural cobblestoning in IPF is caused by retraction of fibrotic scars along interlobular septa, causing the overlying pleural surface to dimple and pucker. On cut surface: the lower lobes show firm, rubbery, white fibrotic areas, most severe in subpleural zones and along septa. The upper lobes may be relatively spared. Microscopy confirms UIP pattern."]','A','Cobblestone pleura = scar retraction along interlobular septa pulling the pleura inward at multiple points. Cut surface: firm, white, rubbery lower lobe fibrosis subpleurally. Hobnail texture on cut surface.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','easy','flashcard','What particle size is most dangerous for pneumoconiosis and why?','["Particles of 1-5 micrometers in diameter are most dangerous because they: (1) bypass mucociliary clearance of the upper respiratory tract and trachea; (2) settle in terminal small airways and alveoli; (3) cannot be expelled by exhalation; (4) are phagocytosed by alveolar macrophages. Particles >10 µm are trapped in nasal turbinates. Particles <0.5 µm may be exhaled without settling."]','A','1-5 µm = Goldilocks zone for pneumoconiosis. Too big (>10 µm) = nose catches them. Too small (<0.5 µm) = exhaled out. 1-5 µm = reaches alveoli and STAYS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','easy','flashcard','What is a ferruginous body and in which pneumoconiosis is it found?','["A ferruginous body (asbestos body) is formed when an asbestos fiber becomes coated with iron-containing protein, giving it a golden-brown color with a beaded or drumstick appearance. Found in: asbestosis (asbestos fiber cores). They are seen in lung biopsies and BAL and confirm significant asbestos exposure. Gomori Prussian blue stain highlights the iron coating."]','A','Ferruginous body = asbestos fiber in iron-protein coat → golden-brown, beaded. Found in BAL or biopsy → confirms asbestos exposure. Also called asbestos bodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','medium','flashcard','Compare the pathologic features of silicosis and coal workers'''' pneumoconiosis (CWP).','["Silicosis: silicotic nodules — concentric whorls of hyalinized collagen (onion-skin pattern) in upper lobes and hilar nodes; eggshell calcification of hilar nodes. CWP: coal macules (dust + macrophages) and coal nodules in upper lobes; simple CWP rarely causes dysfunction; complicated CWP (PMF) = large black scars >2 cm with cavitation."]','A','Silicosis = whorled hyalinized collagen nodules + eggshell LN calcification. CWP = anthracotic coal macules → nodules → PMF (if complicated). Silicosis → TB susceptibility. CWP → PMF progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','medium','flashcard','What are the three malignancies associated with asbestos exposure?','["1) Malignant mesothelioma — most specific to asbestos (amphibole >> chrysotile); very long latency (25-45 years). 2) Bronchogenic carcinoma — risk increased 5-fold with asbestos exposure; 55-fold with asbestos + smoking (synergistic). 3) Other: laryngeal, esophageal, gastric, and colon carcinoma have been reported but are less strongly linked."]','A','Asbestos + Cancer: Mesothelioma (most specific), Bronchogenic carcinoma (most common cancer from asbestos). Asbestos x smoking = 55x lung cancer risk (synergistic, not additive). Long latency of mesothelioma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','medium','flashcard','What is the mechanism of silicosis and describe the histologic appearance of silicotic nodules?','["Mechanism: silica particles phagocytosed by macrophages → activate inflammasome → IL-1/IL-18 release → macrophage activation → fibrogenic cytokines (TGF-beta, TNF) → collagen deposition. Histology: silicotic nodules — concentric layers of hyalinized collagen (onion-skin/whorled pattern) with a cellular outer layer of macrophages/lymphocytes. Upper lobes and hilar nodes."]','A','Silicosis mechanism: macrophage eats silica → inflammasome → IL-1 → fibrosis. Nodule = whorled hyalinized collagen (onion rings). Upper lobes. Eggshell calcification of hilar LN is pathognomonic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','medium','flashcard','How does berylliosis (chronic beryllium disease) differ from other pneumoconioses?','["Unlike silicosis and CWP (which are primarily foreign body fibrogenic reactions), berylliosis is an IMMUNE-MEDIATED (cell-mediated, T cell/Th1) granulomatous reaction to beryllium. Histology: noncaseating granulomas — indistinguishable from sarcoidosis. Diagnosed by beryllium lymphocyte proliferation test (BeLPT). Occurs in aerospace, nuclear, and electronics industries. Genetic susceptibility: HLA-DPB1 Glu69 allele."]','A','Berylliosis = granulomatous (looks like sarcoidosis) + immune-mediated (unlike other pneumoconioses). Key diagnostic test: BeLPT (beryllium lymphocyte proliferation test). Industries: aerospace, nuclear, electronics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','medium','flashcard','What is progressive massive fibrosis (PMF) and what causes it to progress even after dust exposure ceases?','["PMF (complicated CWP): large black fibrotic masses >2 cm developing in <10% of coal workers, typically in upper lobes after many years of exposure. Pathologically: black, hard, rubbery masses with central cavitation (from ischemia or TB). Once PMF develops, progressive self-sustaining inflammation continues even without further dust exposure, leading to pulmonary HTN, cor pulmonale, and respiratory failure."]','A','PMF = complicated CWP, lesions >2 cm, can progress after dust removal. Mechanism of self-propagation: possibly silica component, hypersensitivity, or autoimmune activation. Cause of significant disability and death.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','hard','flashcard','Why do amphibole asbestos fibers cause more disease (especially mesothelioma) than chrysotile?','["Chrysotile (serpentine): curly, pliable fibers; deposited in upper airways and upper bronchi; less able to penetrate to alveoli and interstitium; somewhat soluble and cleared over time. Amphiboles (crocidolite, amosite): straight, rigid, needle-like; penetrate deeply to reach pleura; resist macrophage clearance (biopersistent); generate more reactive oxygen species; more strongly linked to mesothelioma."]','A','Amphiboles > chrysotile for mesothelioma because: straight + needle-like = penetrate to pleura; biopersistent (not cleared). Chrysotile = curly = impacted in upper airways, somewhat cleared over time.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','hard','flashcard','What are the four factors that determine the pathogenicity of inhaled mineral dusts?','["1) Amount of dust retained in the lung — concentration and duration of exposure. 2) Size and shape of particles — 1-5 µm optimal for alveolar deposition; elongated fibers (asbestos) more pathogenic than spherical. 3) Physicochemical reactivity — crystalline silica more reactive than amorphous; amphiboles generate more ROS. 4) Additional effects — co-exposure to tobacco smoke, other dust components; solubility (affects clearance vs. fibrogenesis)."]','A','Four factors: Amount + Size/shape + Reactivity + Additional effects (smoking, solubility). Crystalline > amorphous silica. Elongated fibers (asbestos) more pathogenic than spheres. Smoking synergizes with asbestos for cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pneumoconioses & Occupational Lung Disease','hard','flashcard','What is acute silicosis and how does it differ pathologically from chronic silicosis?','["Acute silicosis (accelerated silicosis): occurs after massive short-term exposure (months to few years, e.g., denim sandblasting). Pathology: accumulation of lipoproteinaceous material in alveoli (PAS positive, identical to pulmonary alveolar proteinosis). Rapidly progressive, often fatal. Chronic silicosis: develops over 10-40 years of moderate exposure. Pathology: whorled hyalinized collagen silicotic nodules in upper lobes."]','A','Acute silicosis = PAS-positive lipoproteinaceous exudate (= PAP-like pattern). Chronic silicosis = whorled hyalinized nodules. Acute = heavy short exposure; Chronic = moderate long exposure. Opposite morphologies!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','easy','flashcard','What are the four stages of lobar pneumonia and what is seen in each stage?','["1) Congestion (day 1-2): lungs heavy, red, boggy; vascular congestion and intra-alveolar edema. 2) Red hepatization (day 2-4): lung red, solid, airless; alveoli filled with neutrophils, RBCs, and fibrin. 3) Grey hepatization (day 4-8): red cell breakdown, fibrin organization; lung grey-brown. 4) Resolution (week 2): enzymatic digestion and resorption of exudate; normal lung architecture restored."]','A','4 stages: Congestion → Red hepatization (RBC+PMN) → Grey hepatization (fibrin+macrophages) → Resolution. Mnemonic: Congestion → Red → Grey → Resolution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','easy','flashcard','What is the most common cause of community-acquired pneumonia in adults?','["Streptococcus pneumoniae (pneumococcus) is the most common cause of community-acquired bacterial pneumonia in adults. It produces IgA protease (destroys mucosal defense), polysaccharide capsule (evades phagocytosis), and pneumolysin. Classic presentation: sudden fever, rigors, pleuritic chest pain, productive cough with rust-colored sputum, lobar consolidation on CXR, Gram-positive diplococci on sputum smear."]','A','S. pneumoniae = #1 CAP. Lancet-shaped Gram-positive diplococci, encapsulated. Rust-colored sputum. Lobar pattern. Optochin-sensitive. PPV-23 and PCV-13 vaccines available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','medium','flashcard','Describe the differences between lobar pneumonia and bronchopneumonia.','["Lobar pneumonia: affects one entire lobe; predominantly S. pneumoniae; airspace-filling exudate via Kohn''''s pores; immunocompetent adults; uniform stage of disease. Bronchopneumonia (lobular): patchy multifocal consolidation centered on bronchi/bronchioles; multiple organisms (S. aureus, Klebsiella, gram-negatives); non-uniform patches of varying age; elderly, debilitated, hospitalized patients, post-viral illness."]','A','Lobar = one lobe + S. pneumo + healthy adults + uniform. Bronchopneumonia = patchy + multiple organisms + sick/elderly + non-uniform. Pores of Kohn spread S. pneumo within a lobe giving the lobar pattern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','medium','flashcard','Describe the primary TB complex and explain why secondary (reactivation) TB has an upper lobe predilection.','["Primary TB: Ghon focus (caseous granuloma in lower/mid-lung parenchyma) + ipsilateral hilar lymph node granuloma = Ghon complex. Secondary TB: reactivation occurs in apical/posterior upper lobes. Reason: higher PO2 in upper lobes favors aerobic M. tuberculosis growth; local cellular immunity may be impaired at the apices."]','A','Primary = Ghon complex (lung focus + hilar LN). Secondary = UPPER LOBE cavitation (high PO2 favors TB growth). Primary in middle/lower zones; secondary in apices.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','medium','flashcard','What is the morphology of PCP (Pneumocystis jirovecii pneumonia) on BAL and biopsy?','["Bronchoalveolar lavage: foamy eosinophilic intra-alveolar exudate containing the organisms. Gomori methenamine silver (GMS) stain or toluidine blue O: shows cup-shaped or crescent-shaped cysts (4-6 µm). Pathology: thickened alveolar walls with interstitial plasma cell infiltrate; NO granulomas. CT: bilateral ground-glass opacities (perihilar). Context: CD4 <200 cells/µL."]','A','PCP = foamy alveolar exudate + cup-shaped cysts on GMS stain. No granulomas. CD4 <200 = high risk. BAL is diagnostic method. CT: bilateral ground-glass. Treat: TMP-SMX.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','medium','flashcard','What is the clinical and pathologic difference between typical and atypical pneumonia?','["Typical (bacterial): acute onset, high fever, pleuritic pain, productive purulent cough, lobar/bronchopneumonia consolidation, neutrophilic alveolar exudate, responds to beta-lactams. Causative: S. pneumoniae, S. aureus, Klebsiella. Atypical (walking pneumonia): milder insidious onset, dry cough, interstitial infiltrates, mononuclear interstitial inflammation WITHOUT alveolar exudate. Causative: Mycoplasma, Chlamydia, Legionella, viruses. Responds to macrolides/doxycycline."]','A','Typical = alveolar exudate + productive cough + consolidation = S. pneumo. Atypical = interstitial inflammation + dry cough + ground glass = Mycoplasma/Chlamydia/Legionella. Atypical does not respond to beta-lactams (no cell wall target).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','medium','flashcard','What organisms most commonly cause hospital-acquired (nosocomial) pneumonia?','["In order of frequency: (1) Gram-negative rods: Pseudomonas aeruginosa, Klebsiella pneumoniae, E. coli, Enterobacter — especially in ICU/ventilated patients. (2) Staphylococcus aureus (MRSA in hospital setting). (3) Aspiration of oropharyngeal flora (mixed anaerobes + gram-negatives). Ventilator-associated pneumonia (VAP) is most severe form."]','A','Nosocomial/VAP: Pseudomonas #1 + Klebsiella + E. coli + MRSA. Broader spectrum coverage needed. VAP = pneumonia >48 hours after intubation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','hard','flashcard','What factors determine whether a lung abscess develops from a lobar pneumonia, and what organisms are most commonly responsible?','["Lung abscesses form when pneumonia organisms produce potent tissue-destroying enzymes: Staphylococcus aureus (staphylokinase, lipases), Klebsiella pneumoniae, and Gram-negative bacteria. Key mechanism: bacterial proteases lyse neutrophil debris creating liquefied necrotic cavity. Aspiration pneumonia (oral anaerobes: Peptostreptococcus, Prevotella, Fusobacterium) is the most common cause overall — right lower/upper lobe posterior segments in supine patients."]','A','Abscess formation: necrotizing bacteria (S. aureus, Klebsiella, Pseudomonas) or aspiration (anaerobes). Aspiration = most common cause → right side > left; posterior segments (supine position). Treat with prolonged antibiotics +/- drainage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','hard','flashcard','Why is the right lower lobe the most common location for aspiration pneumonia and lung abscesses?','["The right mainstem bronchus is more vertical and in more direct alignment with the trachea than the left, making aspirated material more likely to enter the right lung. Within the right lung, gravity directs aspirated material to: the posterior segment of the right upper lobe and the superior segment of the right lower lobe (supine position), or the basilar segments of the right lower lobe (upright). Alcoholics and unconscious patients are at highest risk."]','A','Anatomy: right mainstem bronchus = more vertical + directly in line with trachea = preferred aspiration route. Supine: posterior RUL + superior RLL. Upright: RLL basilar. Most abscesses in right lung.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Infections','hard','flashcard','Describe the epidemiology and clinical features of Legionnaires'''' disease.','["Legionella pneumophila: Gram-negative rod, obligate intracellular parasite of alveolar macrophages. Habitat: water systems (cooling towers, hospital water, air conditioning), transmitted via contaminated aerosols (NOT person-to-person). Incubation 2-10 days. Classic patient: middle-aged male smoker or immunocompromised. Features: high fever, non-productive cough, GI symptoms (diarrhea), mental status changes, relative bradycardia, hyponatremia. Diagnosed by urinary antigen. Treat with fluoroquinolones or macrolides."]','A','Legionella: water aerosols → macrophages. Male smoker or immunocompromised. Hyponatremia + diarrhea + pneumonia = Legionella. Urine antigen test = fastest diagnosis. NOT person-to-person. Intracellular = beta-lactams ineffective alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','easy','flashcard','What are the four major histologic types of lung carcinoma and which is most common?','["1) Adenocarcinoma — most common overall (~40%); peripheral; non-smokers/smokers; EGFR, ALK, KRAS mutations. 2) Squamous cell carcinoma (~25-30%); central; strongly smoking-related; keratin pearls; PTHrP → hypercalcemia. 3) Small cell carcinoma (SCLC, ~15%); central; neuroendocrine; worst prognosis; paraneoplastic syndromes. 4) Large cell carcinoma (~10%); peripheral; diagnosis of exclusion."]','A','Four types: Adeno (peripheral, non-smoker friendly), SCC (central, squamous, smoking), SCLC (central, neuroendocrine, worst), Large cell (peripheral, exclusion). Adeno is #1 overall. SCLC = cannot operate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','easy','flashcard','What are the paraneoplastic syndromes associated with small cell lung carcinoma (SCLC)?','["SCLC paraneoplastic syndromes (due to neuroendocrine hormone secretion): 1) SIADH — ADH secretion → hyponatremia. 2) Cushing syndrome — ACTH secretion → hypokalemia, hyperglycemia, hypertension. 3) Lambert-Eaton myasthenic syndrome — autoantibodies vs VGCC → proximal muscle weakness. 4) Peripheral neuropathy. 5) Encephalomyelitis (anti-Hu antibodies)."]','A','SCLC paraneoplastic: SIADH (ADH), Cushing (ACTH), Lambert-Eaton (VGCC autoAb). Small cells = endocrine glands making hormones = many paraneoplastic syndromes. Lambert-Eaton: weakness IMPROVES with repeated movement (opposite of MG).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','medium','flashcard','Describe the genetic alterations in lung adenocarcinoma and their clinical significance.','["Key driver mutations in adenocarcinoma: EGFR (exon 19 del/exon 21 L858R): ~15% Western, ~50% East Asian; sensitive to erlotinib/gefitinib/osimertinib. ALK rearrangement (~5%): crizotinib/alectinib sensitive. ROS1 rearrangement (~1-2%): crizotinib sensitive. KRAS (~30%): less targetable; sotorasib for KRAS G12C. BRAF (~2%): dabrafenib + trametinib. Molecular profiling is mandatory for advanced adenocarcinoma."]','A','Adenocarcinoma driver mutations: EGFR (East Asian, never-smoker), ALK (young, never-smoker), KRAS (smoker), ROS1 (rare). All need molecular testing → targeted therapy available. EGFR + ALK most clinically important.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','medium','flashcard','What is the difference between adenocarcinoma in situ (AIS), minimally invasive adenocarcinoma (MIA), and invasive adenocarcinoma?','["AIS (formerly BAC): pure lepidic growth — tumor cells spread along pre-existing alveolar walls without stromal, vascular, or pleural invasion; ≤3 cm; 100% 5-year survival with resection. MIA: predominantly lepidic growth with ≤5 mm invasion zone; near 100% survival. Invasive adenocarcinoma: >5 mm invasion; reduced survival; mixed patterns (acinar, papillary, micropapillary, solid, lepidic)."]','A','AIS = lepidic only, no invasion = curable. MIA = lepidic + ≤5mm invasion = near curable. Invasive = >5 mm invasion = standard prognosis. Lepidic pattern = lung scaffold preserved. GGO on CT = think AIS/MIA in non-smoker.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','medium','flashcard','What is squamous cell carcinoma of the lung and what are its characteristic features?','["SCC of lung: (1) Arises centrally in major bronchi; (2) Strongly associated with smoking; (3) Histology: squamous differentiation — keratin pearls, intercellular bridges, p63/p40 positive IHC; (4) Paraneoplastic: PTHrP secretion → hypercalcemia; (5) Tends to cavitate; (6) Can cause obstructive pneumonia distally."]','A','SCC: central + smoking + squamous (keratin pearls) + PTHrP (hypercalcemia) + cavitation. p63/p40 IHC positive. Obstruction → post-obstructive pneumonia distal to mass.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','medium','flashcard','What is Pancoast (superior sulcus) tumor and what is Pancoast syndrome?','["Pancoast tumor: lung carcinoma at the apex (superior sulcus). Clinical syndrome from local invasion: (1) Horner syndrome — ptosis, miosis, anhidrosis from cervical sympathetic chain invasion; (2) Shoulder/arm pain (especially C8-T2) from brachial plexus invasion; (3) Rib and vertebral body destruction. Most commonly SCC or adenocarcinoma. Treated with concurrent chemoradiation followed by surgery if resectable."]','A','Pancoast syndrome = Horner + brachial plexus pain + rib/vertebra destruction. Apex tumor. Horner = ptosis + miosis + anhidrosis (sympathetic chain). Treat: chemoradiation → surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','medium','flashcard','What is the significance of the RB1 gene in small cell lung carcinoma?','["RB1 (retinoblastoma tumor suppressor) is deleted or mutated in nearly 100% of SCLCs. RB1 normally restrains cell cycle progression by inhibiting E2F transcription factors. Its loss leads to uncontrolled cell proliferation. Combined with TP53 loss (present in ~90% of SCLC), these two mutations are virtually universal in SCLC and drive its rapid growth and early metastasis."]','A','SCLC molecular hallmarks: RB1 loss (~100%) + TP53 loss (~90%) = essential drivers. RB1 = cell cycle brake. TP53 = genome guardian. Both lost = rapid proliferation + genomic instability = aggressive SCLC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','hard','flashcard','What is the TNM staging system for non-small cell lung cancer (NSCLC) and what are the key surgical resectability criteria?','["T: T1 (≤3 cm, within lung/visceral pleura); T2 (>3-5 cm or involves main bronchus >2 cm from carina); T3 (>5-7 cm or chest wall/pericardium invasion); T4 (>7 cm or mediastinum/vertebra/carina/great vessels). N: N0 (no nodes); N1 (ipsilateral hilar); N2 (ipsilateral mediastinal or subcarinal); N3 (contralateral or supraclavicular). M: M1 (distant mets). Resectable: generally Stage I-IIB, selected Stage IIIA."]','A','TNM key thresholds: T1=≤3cm, T2=3-5cm, T4=mediastinum. N2=ipsilateral mediastinal. M1=mets. Resectable: Stage I-II (some IIIA). SCLC is NOT staged TNM — limited vs. extensive disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','hard','flashcard','Describe the histology and IHC profile of small cell carcinoma that distinguishes it from other lung tumors.','["Histology: sheets of small cells (2× lymphocyte size) with scant cytoplasm, finely granular chromatin, nuclear molding, frequent mitoses, extensive necrosis, crush artifact from sampling. IHC: positive for neuroendocrine markers (synaptophysin, chromogranin A, CD56/NCAM), TTF-1 (~90%), negative for p40/p63 (squamous). High Ki-67 (>80%)."]','A','SCLC IHC: Synaptophysin+ Chromogranin+ CD56+ TTF-1+ Ki-67 very high. Scant cytoplasm + nuclear molding + crush artifact = classic SCLC look. Distinguished from carcinoid by mitoses and necrosis (carcinoid has <2 mitoses/2mm²).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Lung Carcinoma','hard','flashcard','How does hypertrophic osteoarthropathy (HOA) arise as a paraneoplastic syndrome in lung carcinoma?','["HOA: paraneoplastic periosteal new bone formation affecting distal long bones (radius, ulna, tibia, fibula) causing pain and swelling, often with digital clubbing. Most common in adenocarcinoma and large cell carcinoma (not SCLC). Mechanism unclear — proposed: abnormal platelet activation/VEGF release from tumor bypassing pulmonary filter → periosteal stimulation; or vagal nerve-mediated reflex. Resolves after tumor resection."]','A','HOA = periosteal new bone + clubbing = most common in adenocarcinoma. NOT from SCLC hormone secretion. Mechanism: platelet/VEGF bypass of pulmonary filter OR vagal reflex. Clubbing + bone pain = think HOA = think adenocarcinoma.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','easy','flashcard','What is the source of >95% of pulmonary emboli and what are the main risk factors?','["Source: deep veins of lower extremities (deep vein thrombosis, DVT) — >95% of cases. Risk factors (Virchow''''s triad): (1) Stasis — immobility, heart failure, prolonged travel, surgery; (2) Hypercoagulability — pregnancy, OCP, cancer, inherited thrombophilias (Factor V Leiden, protein C/S deficiency); (3) Endothelial injury — trauma, surgery. Factor V Leiden is the most common inherited thrombophilia."]','A','Source: leg DVT >95%. Virchow''''s triad: Stasis + Hypercoagulability + Endothelial injury. Factor V Leiden = most common inherited cause. OCP + smoking = high synergistic risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','easy','flashcard','Why are most pulmonary emboli clinically silent and what percentage cause infarction?','["Most pulmonary emboli (~60%) are clinically silent because: (1) dual blood supply (pulmonary + bronchial arteries) prevents infarction in most cases; (2) emboli are small and peripherally located; (3) the underlying lung is healthy. Only ~10% of PEs cause pulmonary infarction, occurring when bronchial circulation is insufficient. Massive PE (saddle embolus) causes cardiovascular collapse/sudden death (~5%)."]','A','~60% silent. ~10% cause infarction (hemorrhagic, wedge-shaped). ~5% cause sudden death (saddle embolus). Dual blood supply (bronchial + pulmonary) = protective. Infarction more likely if bronchial supply already compromised (heart failure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','medium','flashcard','Describe the gross and microscopic appearance of a pulmonary infarct.','["Gross: wedge-shaped, pleura-based, hemorrhagic (red-brown), with the apex pointing toward the hilum. May develop central grey color as blood breaks down. Pleural fibrinous exudate overlying the infarct. Microscopic: initial — coagulative necrosis of alveolar walls and septa; alveolar spaces filled with blood. Organizing phase: fibroblasts invade, eventually producing a fibrotic scar."]','A','Pulmonary infarct: wedge-shaped (apex → hilum) + hemorrhagic + pleural-based. Hampton''''s hump on CXR. Hemorrhagic because bronchial circulation continues to perfuse the infarcted tissue.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','medium','flashcard','What are the WHO groups of pulmonary hypertension?','["WHO Group 1: Pulmonary arterial hypertension (PAH) — idiopathic, heritable (BMPR2), drug-induced, CTD, HIV, portal. Group 2: Left heart disease (most common cause globally). Group 3: Lung disease/hypoxia — COPD, IPF, sleep apnea. Group 4: Chronic thromboembolic PH (CTEPH) — organized clot. Group 5: Multifactorial/unclear — sarcoidosis, sickle cell, metabolic."]','A','5 WHO groups: 1=PAH (idiopathic, BMPR2), 2=Left heart (most common), 3=Lung disease/hypoxia, 4=CTEPH (clots), 5=Miscellaneous. Group 2 (left heart disease) is the most common cause of elevated PA pressure worldwide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','medium','flashcard','What vascular histologic changes occur in the development of pulmonary arterial hypertension from mild to severe?','["Progressive vascular remodeling: (1) Medial hypertrophy — smooth muscle proliferation thickening the media. (2) Intimal proliferation — fibroblasts and smooth muscle cells form laminar intimal fibrosis. (3) Adventitial thickening. (4) Atherosclerotic plaques in large pulmonary arteries. (5) Plexiform lesion (most severe) — glomeruloid proliferation of endothelial channels within a dilated small artery = pathognomonic of severe/irreversible PAH."]','A','PAH histologic progression: Medial hypertrophy → Intimal proliferation → Atherosclerosis → PLEXIFORM LESION (most severe, pathognomonic of advanced PAH). Plexiform = endothelial channels in aneurysmal dilation of small arteries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','medium','flashcard','What is the prognosis and treatment of idiopathic PAH?','["Without treatment: median survival 2-3 years from diagnosis; 80% die within 5 years. With modern therapy: improved but not curative. Treatments target three pathways: (1) Prostacyclin pathway — epoprostenol (IV), iloprost; (2) Endothelin pathway — bosentan, ambrisentan; (3) Nitric oxide pathway — sildenafil, tadalafil (PDE5 inhibitors). Lung transplantation is the only cure."]','A','IPH treatment targets: (1) Prostacyclin (PGI2) analogs; (2) Endothelin receptor antagonists; (3) PDE5 inhibitors (sildenafil). Three pathways, all cause vasodilation/anti-remodeling. Prognosis poor without treatment. Only cure = lung transplant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','medium','flashcard','What is Goodpasture syndrome and how is it diagnosed?','["Goodpasture syndrome: autoimmune disease with circulating anti-GBM (glomerular basement membrane) antibodies directed against the NC1 domain of alpha-3 chain of type IV collagen, which is present in both GBM and alveolar basement membrane. Results in: (1) diffuse pulmonary hemorrhage (hemoptysis, infiltrates); (2) rapidly progressive glomerulonephritis (RPGN). Diagnosis: anti-GBM antibodies in serum; linear IgG deposits on immunofluorescence of kidney biopsy. Treat: plasmapheresis + steroids + cyclophosphamide."]','A','Goodpasture: anti-GBM Ab → pulmonary hemorrhage + RPGN. Antigen = NC1 domain of alpha-3 chain type IV collagen. Linear IgG on IF = pathognomonic. Plasmapheresis to remove Ab. Young males most affected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','hard','flashcard','Explain the electromechanical dissociation (PEA) seen in massive pulmonary embolism.','["In massive (saddle) pulmonary embolism: the main pulmonary artery or major branches are occluded. Right ventricular outflow is suddenly obstructed → acute RV failure. The left ventricle receives no blood from pulmonary circulation → sudden drop in cardiac output → no palpable pulse or BP. However, the cardiac conduction system continues to generate normal electrical impulses → ECG shows organized rhythm without mechanical output = pulseless electrical activity (PEA)."]','A','Massive PE → sudden obstruction of pulmonary outflow → no LV filling → no cardiac output → PEA (heart generates rhythm but no pulse). Classic emergency scenario. S1Q3T3 on ECG. Treat: thrombolytics, catheter-directed therapy, surgical embolectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','hard','flashcard','What are plexiform lesions and in which conditions are they seen?','["Plexiform lesions are glomeruloid vascular structures formed within dilated small muscular pulmonary arteries (typically 40-300 µm diameter). They consist of a network of thin-walled channels lined by endothelial cells, creating a tuft or glomeruloid appearance. They represent the most severe form of pulmonary vascular remodeling and are associated with: idiopathic PAH, heritable PAH (BMPR2), CTD-associated PAH, and congenital heart disease with Eisenmenger syndrome."]','A','Plexiform = glomeruloid endothelial proliferation in small pulmonary arteries. Irreversible PAH marker. Seen in: idiopathic PAH, BMPR2 hereditary, CTD-PAH, Eisenmenger. Not seen in Groups 2-5 (left heart, lung disease, CTEPH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pulmonary Vascular Disease','hard','flashcard','What drives BMPR2 mutation-related PAH and why is penetrance incomplete?','["BMPR2 (bone morphogenetic protein receptor type 2) normally inhibits smooth muscle cell proliferation in pulmonary arteries. Loss-of-function BMPR2 mutations → unchecked pulmonary artery smooth muscle cell proliferation and endothelial cell dysfunction → vascular remodeling → PAH. Penetrance is ~20% in females, ~14% in males — incomplete because a second hit or additional cofactors are required to trigger clinically overt disease (two-hit model)."]','A','BMPR2 loss → uninhibited SMC proliferation in pulmonary arteries → PAH. Incomplete penetrance (20% females, 14% males) = two-hit model: germline mutation + second trigger needed. Female sex hormones paradoxically increase prevalence in women despite lower penetrance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','easy','flashcard','Distinguish between transudative and exudative pleural effusions using Light''''s criteria.','["Light''''s criteria — exudate meets at least ONE: (1) Pleural fluid protein/serum protein ratio >0.5; (2) Pleural fluid LDH/serum LDH ratio >0.6; (3) Pleural fluid LDH >2/3 of upper limit of normal serum LDH. Transudate: none of above criteria met. Causes of transudates: CHF, cirrhosis, nephrotic syndrome. Causes of exudates: pneumonia, cancer, TB, pulmonary embolism, rheumatoid arthritis."]','A','Light''''s criteria: exudate = Protein ratio >0.5 OR LDH ratio >0.6 OR LDH >2/3 ULN. CHF = transudate. PNA/cancer/TB = exudate. Mnemonic: Lights exude the truth — if ANY criteria met = exudate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','easy','flashcard','What are the main causes of pleural effusion in each category?','["Transudates: CHF (#1), hepatic cirrhosis (hepatic hydrothorax), nephrotic syndrome, Meigs syndrome. Exudates: infectious (parapneumonic, empyema, TB), malignancy (lung, breast, lymphoma, mesothelioma), pulmonary embolism, rheumatoid arthritis/SLE, pancreatitis, post-CABG. Other: hemothorax (blood), chylothorax (lymph/chyle), urinothorax."]','A','Transudate causes: CHF, cirrhosis, nephrotic syndrome (LOW oncotic/HIGH hydrostatic). Exudate causes: infection/cancer/PE/CTD (increased pleural permeability). Chylothorax = milky fluid = lymphatic obstruction (e.g., lymphoma).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','medium','flashcard','What is malignant mesothelioma and what are its histologic and IHC features?','["Malignant mesothelioma: aggressive pleural tumor from mesothelial cells, strongly linked to amphibole asbestos exposure (25-45 year latency). Histology: biphasic — epithelioid component (tubular/papillary structures) and sarcomatoid component (spindle cells in storiform pattern). IHC: positive for calretinin, WT-1, D2-40 (podoplanin), CK5/6, mesothelin; negative for CEA, TTF-1, Napsin-A."]','A','Mesothelioma markers: POSITIVE = Calretinin, WT-1, D2-40, CK5/6. NEGATIVE = CEA, TTF-1, Napsin-A (rule out adenocarcinoma). Biphasic = epithelioid + sarcomatoid. Amphibole exposure. 25-45 year latency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','medium','flashcard','What is empyema and what are the stages of pleural infection?','["Empyema = pus in the pleural cavity. Stages: (1) Exudative — free-flowing thin pleural fluid; manageable with antibiotics + drainage. (2) Fibrinopurulent — fibrin deposits form loculations; thickened pleura; requires image-guided drainage or fibrinolysis. (3) Organizing — fibroblasts invade fibrin; thick fibrous cortex (pleural peel) traps lung; may require decortication surgery. Causative organisms: S. aureus, S. pneumoniae, gram-negatives, oral anaerobes."]','A','Empyema stages: Exudative (drain easily) → Fibrinopurulent (loculated, harder to drain) → Organized (peel, needs decortication). Earlier = simpler treatment. Treat empyema with antibiotics + drainage regardless of stage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','medium','flashcard','What is spontaneous pneumothorax and how does it differ from tension pneumothorax?','["Spontaneous pneumothorax: air enters pleural space without trauma, usually from rupture of a subpleural bleb in young males. Simple — air enters but no one-way valve; pressure equalizes and lung partially collapses. Tension pneumothorax: one-way valve mechanism — air enters on inspiration, cannot exit on expiration; intrapleural pressure progressively rises above atmospheric; mediastinum shifts away; cardiac output falls; life-threatening emergency requiring immediate needle decompression."]','A','Spontaneous: bleb rupture, young male, air enters, equilibrates, partial collapse. Tension: one-way valve → pressure keeps rising → mediastinal shift AWAY from affected side → obstructive shock → needle decompression (2nd ICS, MCL, affected side).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','medium','flashcard','What is the clinical significance of pleural plaques in asbestos-exposed individuals?','["Pleural plaques are localized areas of parietal pleural fibrosis forming after asbestos exposure. Key features: (1) Usually asymptomatic; (2) Detected radiographically or at autopsy; (3) Most commonly on parietal pleura over lower lobes and diaphragm; (4) May calcify; (5) Indicate significant asbestos exposure but do NOT directly indicate asbestosis (parenchymal fibrosis) or predict mesothelioma development."]','A','Pleural plaques: asymptomatic + calcified + parietal pleura = asbestos EXPOSURE marker. Do NOT = parenchymal asbestosis. Do NOT directly predict mesothelioma. Important: medicolegally establishes asbestos exposure history.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','medium','flashcard','What are the clinical features and HRCT findings of malignant mesothelioma?','["Clinical: dyspnea (effusion), chest pain (pleural invasion), weight loss. HRCT: nodular or lobular pleural thickening (often >1 cm), encasement of entire hemithorax by tumor (rind), pleural effusion, loss of hemithoracic volume, invasion of mediastinum or chest wall. Diagnosis: pleural biopsy (VATS or image-guided). Prognosis: 9-12 months median; slightly better for epithelioid subtype."]','A','Mesothelioma HRCT: nodular pleural thickening encasing the lung (rind) + pleural effusion. Epithelioid = slightly better prognosis than sarcomatoid. Serum mesothelin = emerging biomarker.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','hard','flashcard','In compression vs. resorption atelectasis, how does the direction of mediastinal shift help distinguish the cause?','["Compression atelectasis: external compression by pleural effusion, air, or tumor collapses adjacent lung. Mediastinum shifts AWAY from the affected side (pushed by the compressing fluid/air). Resorption atelectasis: bronchial obstruction (mucus plug, tumor, foreign body) causes distal air absorption by blood. Mediastinum shifts TOWARD the affected side (collapsed lung creates negative pressure, pulling mediastinum)."]','A','Mediastinal shift: TOWARD affected side = resorption atelectasis (obstruction). AWAY from affected side = compression atelectasis (fluid/air/tumor) OR tension pneumothorax. This simple rule distinguishes the two main mechanisms on CXR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','hard','flashcard','What distinguishes rheumatoid pleural effusion from other exudates?','["Rheumatoid pleuritis: (1) Exudate with very LOW glucose (<30 mg/dL — unique to RA); (2) Very low pH (<7.2); (3) Very high LDH; (4) Low complement (C3, C4); (5) Predominantly lymphocytic/mononuclear; (6) May contain cholesterol crystals in chronic effusions (pseudochylothorax). The extremely low glucose is caused by impaired glucose transport across the inflamed pleura and high metabolic activity of inflammatory cells."]','A','RA effusion: glucose <30 mg/dL (LOWEST of all effusion types), pH <7.2, high LDH, low complement. Key: only RA and empyema have glucose this low — RA lacks turbid gross appearance and positive bacterial culture of empyema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Pleural Disease','hard','flashcard','What is a chylothorax and what are the most common causes?','["Chylothorax: accumulation of lymph (chyle) in the pleural space due to disruption or obstruction of the thoracic duct. Characteristics: milky/opalescent pleural fluid; triglyceride >110 mg/dL; lymphocyte-predominant. Causes: (1) Malignancy — lymphoma most common (tumor invasion/obstruction of thoracic duct); (2) Trauma — thoracic surgery, penetrating injury; (3) Idiopathic; (4) Non-traumatic: filariasis in developing countries. Treatment: drainage + fat-free diet/TPN; pleurodesis or surgical ligation if persistent."]','A','Chylothorax = milky fluid + TG >110 + lymphocytes. Causes: Lymphoma #1, surgery, trauma. Thoracic duct disrupted. Treat: fat-free diet/TPN + drainage → pleurodesis. Separate from pseudochylothorax (chronic effusion with cholesterol crystals).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','easy','flashcard','What is neonatal RDS and who is at risk?','["Neonatal RDS (hyaline membrane disease): surfactant deficiency causing alveolar collapse and respiratory distress in premature infants. At risk: (1) Premature infants (<35 weeks) — immature type II pneumocytes; (2) Infants of diabetic mothers (hyperinsulinism suppresses cortisol-stimulated surfactant synthesis); (3) Cesarean section before labor; (4) Male sex; (5) Second-born twin; (6) Perinatal asphyxia."]','A','RDS risk factors: prematurity (<35 wk) + IDM (insulin suppresses cortisol) + C-section before labor + male sex. Everything that REDUCES cortisol or TYPE II CELL maturity = increases RDS risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','easy','flashcard','What are hyaline membranes and where are they located in neonatal RDS?','["Hyaline membranes: waxy, eosinophilic membranes lining the respiratory bronchioles and alveolar ducts in neonatal RDS. Composition: fibrin-rich edema fluid + cytoplasmic remnants of necrotic type I and type II pneumocytes + lipid remnants. They form within 4-6 hours of birth. Hyaline = glassy appearance (homogeneous eosinophilic material). Same type of membranes seen in ARDS in adults (diffuse alveolar damage/DAD)."]','A','Hyaline membranes = fibrin + necrotic epithelial cell remnants. Line respiratory BRONCHIOLES and ALVEOLAR DUCTS (not alveoli initially). Appear within hours. Present in BOTH neonatal RDS and adult ARDS (DAD).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','medium','flashcard','What are the components of surfactant and which cell produces it?','["Surfactant is produced by TYPE II PNEUMOCYTES (alveolar type II cells), stored in lamellar bodies, and secreted into the alveolar space. Composition: ~90% lipids (dipalmitoylphosphatidylcholine/DPPC is the key active component that reduces surface tension) + ~10% proteins (SP-A, SP-B, SP-C, SP-D). SP-B and SP-C are essential for surface tension reduction. SP-A and SP-D are collectins involved in host defense."]','A','Surfactant made by: TYPE II PNEUMOCYTES → lamellar bodies → alveolar space. Main lipid: DPPC. Key proteins: SP-B and SP-C = surface tension reduction. SP-A and SP-D = immunity. ABCA3 mutations affect lamellar body lipid trafficking.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','medium','flashcard','How do maternal corticosteroids reduce the risk of neonatal RDS?','["Antenatal corticosteroids (betamethasone or dexamethasone) given to mothers at 24-34 weeks at risk of preterm delivery: (1) Cross the placenta and bind glucocorticoid receptors in fetal type II pneumocytes; (2) Upregulate surfactant protein genes (SFTPA, SFTPB, SFTPC) and ABCA3; (3) Promote structural maturation of type II cells; (4) Reduce alveolar permeability and fluid accumulation. Effect seen within 24-48 hours; maximal at 48 hours. Reduces RDS incidence and severity by ~50%."]','A','Antenatal betamethasone: given 24-34 weeks → crosses placenta → stimulates type II pneumocyte maturation → surfactant synthesis increases. Effect in 24-48 hrs, maximal at 48 hrs. Reduces RDS by ~50%. Standard of care for threatened preterm delivery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','medium','flashcard','How does exogenous surfactant therapy work in neonatal RDS?','["Exogenous surfactant replacement: natural or synthetic surfactant preparations (beractant, poractant alfa, calfactant) are instilled directly into the trachea via endotracheal tube. They replenish deficient surfactant, immediately reducing alveolar surface tension, improving lung compliance, reducing atelectasis, and improving V/Q matching and oxygenation. Combined with mechanical ventilation, this treatment has reduced RDS mortality from ~5000/year to <900/year in the US."]','A','Surfactant replacement: into ETT → replaces deficient surfactant → surface tension decreases → alveoli open → compliance increases → oxygenation improves. Immediate effect. Combined with antenatal steroids = major reason RDS mortality fallen dramatically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','medium','flashcard','What is bronchopulmonary dysplasia (BPD) and what are its risk factors?','["BPD: chronic lung disease of prematurity occurring in infants who required mechanical ventilation and supplemental oxygen for neonatal RDS. Pathogenesis: (1) Barotrauma from positive pressure ventilation damages immature lungs; (2) Oxygen toxicity → oxidative stress → inflammation; (3) Arrested alveolar development (fewer, larger alveoli); (4) Airway remodeling with fibrosis. Risk factors: extreme prematurity (<28 weeks), low birth weight, high FiO2 and ventilator pressures, infection, patent ductus arteriosus."]','A','BPD = premature lung + mechanical ventilation + high O2 → chronic lung disease. Pathology: big simplified alveoli (arrested development) + fibrosis + airway remodeling. New BPD (post-surfactant era) = mainly developmental arrest; Old BPD = mainly fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','medium','flashcard','Compare croup (laryngotracheobronchitis) and epiglottitis: causative organisms, age, clinical features, and radiology.','["CROUP: Parainfluenza virus (most common), age 6 months to 3 years. Gradual onset low-grade fever, barking (seal-like) cough, inspiratory stridor, subglottic edema. CXR: steeple sign (subglottic narrowing). Rarely life-threatening. EPIGLOTTITIS: H. influenzae type b (now rare with HiB vaccine), age 2-7 years. Rapid onset high fever >39°C, toxic-appearing, muffled voice, drooling, tripod posture. CXR lateral: thumbprint sign (swollen epiglottis). AIRWAY EMERGENCY."]','A','Croup = barking cough + steeple sign + parainfluenza = not immediately life-threatening. Epiglottitis = drooling + tripod + thumbprint sign + H. influenzae b = AIRWAY EMERGENCY. HiB vaccine has nearly eliminated epiglottitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','hard','flashcard','What is the role of type II pneumocytes in alveolar repair after neonatal RDS?','["After injury to alveolar type I cells (which cover 95% of alveolar surface but cannot proliferate), TYPE II PNEUMOCYTES proliferate to replace them. Type II cells are the stem cells of the alveolar epithelium: they are cuboidal, contain lamellar bodies, are proliferative, and can differentiate into flat type I pneumocytes, restoring the alveolar surface. In the organizing phase of neonatal RDS/DAD, prominent type II cell hyperplasia is the hallmark of early recovery."]','A','Type II cells = alveolar stem cells. Type I cells cover 95% of alveolar surface but CANNOT proliferate. After injury: Type II proliferates → differentiates into Type I → repairs alveolus. Type II hyperplasia in organizing phase = early recovery sign in RDS/DAD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','hard','flashcard','Describe the pathologic sequence in neonatal RDS from surfactant deficiency to hyaline membrane formation.','["Sequence: (1) Surfactant deficiency → increased alveolar surface tension (Laplace''''s law: smaller alveoli collapse). (2) Atelectasis → V/Q mismatch → hypoxemia. (3) Hypoxemia → pulmonary vasoconstriction (like fetal circulation) → right-to-left shunting through foramen ovale/ductus arteriosus. (4) Poor perfusion → ischemic epithelial necrosis of type I cells and distal airway epithelium. (5) Necrotic cells + fibrin-rich edema = hyaline membranes form within 4-6 hours."]','A','Sequence: no surfactant → surface tension increases → alveolar collapse → hypoxemia → ischemia → epithelial necrosis → fibrin + necrotic debris = hyaline membrane. Laplace''''s law: smaller radius → more wall tension → smaller alveoli collapse first.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pathology','Neonatal & Paediatric Respiratory','hard','flashcard','What are the genetic causes of surfactant dysfunction disorders and how do they present differently from premature RDS?','["Genetic surfactant dysfunction disorders (rare): (1) SP-B deficiency (SFTPB mutations): autosomal recessive, complete absence of SP-B → fatal neonatal respiratory failure at term; no response to surfactant therapy. (2) SP-C mutations (SFTPC): usually autosomal dominant, presents as childhood or adult ILD (NSIP pattern). (3) ABCA3 mutations: most common genetic surfactant disorder; neonatal respiratory failure in near-term/term infants in first months of life. Unlike premature RDS, these occur in TERM infants."]','A','Genetic surfactant disorders present in TERM infants (NOT premature). SP-B absence = lethal in newborn, unresponsive to surfactant. ABCA3 = most common genetic surfactant disorder, early months of life. SP-C = childhood/adult ILD. Key: term infant with RDS + no response to surfactant = think genetic cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
